// Convierte un ejercicio validado al formato interno de CampoBase (para sesiones, filtros, etc.).
export function toCampoBaseExercise(item) {
  const dr = item.datos_rapidos || {};
  const media = item.media || {};
  const org = item.organizacion || {};
  
  let playersStr = dr.jugadores || '';
  if (!playersStr && org.jugadores_min) {
    playersStr = `${org.jugadores_min}${org.jugadores_max ? '-' + org.jugadores_max : ''} jugadores`;
  }
  
  let materialStr = dr.material || '';
  if (!materialStr && Array.isArray(item.materiales) && item.materiales.length) {
    materialStr = item.materiales.map(m => (m.cantidad ? m.cantidad + ' ' : '') + m.nombre).join(', ');
  }

  const rawFormato = item.formato_juego || item.clasificacion?.formato_juego || item.formato || item.format;
  const formato_juego = normalizeFormatoJuego(rawFormato);

  return {
    id: item.id,
    recordType: 'exercise',
    name: item.nombre,
    category: item.categoria || 'Técnico-táctico',
    formato_juego,
    formatos_juego: Array.isArray(item.formatos_juego) && item.formatos_juego.length ? item.formatos_juego : (formato_juego === 'futbol_7' ? ['futbol_7'] : (formato_juego === 'futbol_11' ? ['futbol_11'] : ['futbol_7', 'futbol_11'])),
    format: formato_juego === 'futbol_7' ? 'F7' : 'F11',
    players: playersStr,
    material: materialStr,
    duration: parseDuration(dr.duracion),
    description: item.objetivo_principal || '',
    works: Array.isArray(item.que_se_trabaja) ? item.que_se_trabaja : [],
    favorite: false,
    example: false,
    validated: true,
    source: 'validado',
    video: media.video || media.mp4 || media.mp4_url || '',
    preview: media.preview || media.preview_url || media.poster_url || '',
    space: dr.espacio || item.montaje?.dimensiones || '',
    variants: (item.variantes || []).join('\n'),
    createdAt: 1,
    updatedAt: 1,
  };
}

// "14-16 min" -> 15 (valor medio para el descuento de sesión).
function parseDuration(text) {
  const str = String(text ?? '');
  const match = str.match(/(\d+)\s*-\s*(\d+)/);
  if (match) return Math.round((Number(match[1]) + Number(match[2])) / 2);
  const single = str.match(/(\d+)/);
  return single ? Number(single[1]) : 15;
}

