export function findValidatedExercise(id) {
  const found = EJERCICIOS_VALIDADOS.find((item) => item.id === id);
  if (found) return found;
  if (id === LEGACY_FALLBACK.id) return LEGACY_FALLBACK;
  return undefined;
}
